import {createCalendar} from '../domain/time/calendar.js';
import {WORLD_TASKS,modularWorldConfig,selectedWorldVersions} from '../domain/world-dynamics/tasks.js';
import {mainNavigation,rootTitle} from './navigation.js';
import {WORLD_KINDS} from '../domain/world-dynamics/data.js';
import {worldFields} from '../domain/world-dynamics/output.js';
import {worldDateText} from '../domain/world-dynamics/prompts.js';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,attrs='',kind='tertiary')=>`<button type="button" class="ui-button ui-button--${kind}" data-world-action="${action}" ${attrs}>${label}</button>`;
const field=(label,path,value,type='text')=>`<label class="ui-field time-field"><span class="ui-field__label">${label}</span><input class="ui-input" data-world-field="${path}" type="${type}" ${type==='number'?'min="1"':''} value="${e(value)}"></label>`;
const area=(label,path,value,prompt=false)=>`<label class="ui-field time-field"><span class="ui-field__label">${label}</span><textarea class="ui-input time-textarea${prompt?' lt-prompt-editor':''}" data-world-field="${path}">${e(value)}</textarea></label>`;
const switchControl=(label,path,value)=>`<button type="button" class="ui-switch" role="switch" aria-label="${e(label)}" aria-checked="${!!value}" data-world-action="toggle" data-path="${path}"><span class="ui-switch__track"><span class="ui-switch__knob"></span></span></button>`;
const toggle=(label,path,value)=>`<div class="time-reminder-row"><span>${e(label)}</span>${switchControl(label,path,value)}</div>`;
const group=(title,body)=>`<section class="time-prompt-group"><h2 class="time-group-heading">${e(title)}</h2><div class="time-group-body">${body}</div></section>`;
const readRow=(label,value)=>`<div class="time-management-row"><span>${e(label)}</span><small>${e(value)}</small><span></span></div>`;
function disclosure(s,key,label,body,control=''){return `<details class="time-category time-prompt-group time-world-disclosure" data-world-open="${e(key)}" ${s.consoleOpen?.[key]?'open':''}><summary class="time-group-heading"><span${control?' class="time-item-main"':''}>${e(label)}</span>${control}</summary><div class="time-group-body time-stack">${body}</div></details>`;}
function themesBody(c){return c.themes.map((t,i)=>group(t.name,toggle('启用此主题',`themes.${i}.enabled`,t.enabled)+area('主题内容',`themes.${i}.content`,t.content))).join('');}
function ideasBody(c){return c.ideas.map((t,i)=>group(t.name||'新灵感',toggle('启用此灵感',`ideas.${i}.enabled`,t.enabled)+field('名称',`ideas.${i}.name`,t.name)+area('内容',`ideas.${i}.content`,t.content)+button('删除灵感','remove-idea',`data-index="${i}"`,'danger'))).join('')+button('新增灵感','add-idea');}
function materialsBody(s){const c=s.draft;return `<div class="time-stack">${group('世界与人物',`<button type="button" class="time-management-row" data-world-action="books" data-purpose="worldRefs"><span>世界资料</span><small>${c.worldRefs.length} 条</small><span aria-hidden="true">›</span></button><button type="button" class="time-management-row" data-world-action="books" data-purpose="characterRefs"><span>人物资料</span><small>${c.characterRefs.length} 条</small><span aria-hidden="true">›</span></button>`)}${field('补充人物姓名','extraPeople',c.extraPeople)}${area('补充资料','extra',c.extra)}${group('自动带入',readRow('当前日期',s.time.currentDate?.day!=null?worldDateText(s.time.currentDate):'尚未识别')+readRow('近期节日','从时间记录读取')+readRow('已有长期剧情库',`${selectedWorldVersions(s.domain,c).filter(v=>v.kind==='plot').flatMap(v=>v.entries).length} 条`)+readRow('上一版世界动态',s.domain.current?'已有成果':'无'))}${toggle('读取新增剧情正文','readStory',c.readStory)}<div class="time-stack" data-world-story-controls ${c.readStory?'':'hidden'}><fieldset class="time-radio-field lt-summary-modes"><legend class="ui-field__label">首次读取正文</legend><div>${[['all','全部'],['recent','最近X楼']].map(([value,label])=>`<label class="lt-mode"><input type="radio" data-world-field="initialScope" name="world-initial-scope" value="${value}" ${c.initialScope===value?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset><div data-world-recent-count ${c.initialScope==='recent'?'':'hidden'}>${field('最近楼数','initialCount',c.initialCount,'number')}</div></div>${area('本次补充要求','notes',c.notes)}</div>`;}
function consoleBody(s){const c=s.draft,migration=modularWorldConfig(c),tasks=c.taskModules?Object.entries(WORLD_TASKS).map(([kind,label])=>disclosure(s,`task-${kind}`,label,area('任务与输出格式',`taskModules.${kind}.content`,c.taskModules[kind].content,true)+(kind==='region'?themesBody(c):kind==='plot'?ideasBody(c):''),switchControl('启用'+label,`taskModules.${kind}.enabled`,c.taskModules[kind].enabled))).join('')+area('完结影响（公共规则）','commonTasks',c.commonTasks,true):area('原任务区（保留原文）','sections.tasks',c.sections.tasks,true),design=c.taskModules?area('准备与事实检查','commonDesign.before',c.commonDesign.before,true)+Object.entries(WORLD_TASKS).map(([kind,label])=>area(label,`taskModules.${kind}.design`,c.taskModules[kind].design,true)).join('')+area('整体与交付检查','commonDesign.after',c.commonDesign.after,true):area('原设计区（保留原文）','sections.design',c.sections.design,true);return `<div class="time-stack">${migration.error?`<p class="lt-error">${e(migration.error)}</p>`:''}${disclosure(s,'identity','AI 身份区',area('身份与目标','sections.identity',c.sections.identity,true))}${disclosure(s,'rules','基本规则',area('基本规则','sections.rules',c.sections.rules,true))}${disclosure(s,'materials','资料区',materialsBody(s))}${disclosure(s,'tasks','任务区',tasks)}${disclosure(s,'design','设计思考区',design)}</div>`;}
function booksBody(s){return `<div class="time-stack">${s.bookList.length?s.bookList.map(b=>`<details class="time-category time-prompt-group time-world-disclosure" open><summary class="time-group-heading">${e(b.book)}</summary><div class="time-group-body time-stack">${b.entries.map(entry=>{const checked=s.draft[s.bookPurpose].some(ref=>ref.book===entry.book&&ref.uid===entry.uid);return `<details class="time-candidate-evidence time-world-disclosure" data-world-open="${e('book:'+JSON.stringify([entry.book,entry.uid]))}" ${s.consoleOpen?.['book:'+JSON.stringify([entry.book,entry.uid])]?'open':''}><summary><input type="checkbox" data-world-ref data-book="${e(entry.book)}" data-uid="${e(entry.uid)}" aria-label="选择${e(entry.name)}" ${checked?'checked':''}><span>${e(entry.name)}</span></summary><p class="time-evidence-text">${e(entry.content)}</p></details>`;}).join('')}</div></details>`).join(''):'<p class="lt-meta">当前没有可选择的关联世界书条目</p>'}</div>`;}

function entryCard(entry,book,currentDate,version){const f=worldFields(entry.text),name=f.名称??f.姓名??f.事件??WORLD_KINDS[entry.kind],timing=f.时间??(f.有效至?`有效至 ${f.有效至}`:'');const body=f.动向内容??f.动态内容??f.活动内容??f.舆论内容??f.动态??f.影响??'';const edit=book?button('编辑','entry',`data-id="${entry.id}" aria-label="编辑${e(name)}"`):`<button type="button" class="ui-icon-button ui-button--tertiary" data-world-action="entry" data-id="${entry.id}" aria-label="编辑${e(name)}"><img class="lt-icon" src="${new URL('./icons/edit.svg',import.meta.url)}" alt=""></button>`;
 if(entry.kind==='weather'){
  let today='',future=[];try{const cal=createCalendar(version.calendar);cal.validate(currentDate);for(const line of entry.text.split('\n')){const m=line.match(/^(\d{1,4})(?:年|[-/])(\d{1,2})(?:月|[-/])(\d{1,2})日?：\s*(.+)$/);if(!m)continue;const day=cal.validate({calendarId:version.calendar.id,year:+m[1],month:+m[2],day:+m[3]}),difference=cal.compare(day,currentDate);if(difference===0)today=line;else if(difference>0)future.push(line);}}catch{/* Another calendar or no complete current day has no matching forecast. */}
  return `<section class="time-prompt-group time-world-group"><h2 class="time-group-heading">天气环境</h2><div class="time-group-body"><article class="time-item time-record"><div class="time-item-main">${f.地点?`<p class="lt-meta">${e(f.地点)}</p>`:''}<p class="time-evidence-text" data-world-weather-today>${e(today||'暂无当天预报')}</p>${future.length?`<details class="time-category time-world-disclosure"><summary>后续天气</summary><p class="time-evidence-text">${e(future.join('\n'))}</p></details>`:''}</div><div class="time-record-actions">${edit}</div></article></div></section>`;
 }
 if(entry.kind==='plot'){const firstNode=(entry.text.split('关键节点：')[1]??'').split('\n').map(line=>line.trim()).find(Boolean)??f.关键节点??'';return `<section class="time-prompt-group time-world-group"><h2 class="time-group-heading">${e(name)}</h2><div class="time-group-body"><article class="time-item time-record"><div class="time-item-main">${timing?`<p class="lt-meta">${e(timing)}</p>`:''}<p class="time-evidence-text" data-world-plot-first>${e(firstNode)}</p><details class="time-category time-world-disclosure"><summary>完整剧情</summary><p class="time-evidence-text">${e(entry.text)}</p></details></div><div class="time-record-actions">${edit}</div></article></div></section>`;}
 return `<article class="time-item time-record"><div class="time-item-main"><h3>${e(name)}</h3>${timing?`<p class="lt-meta">${e(timing)}</p>`:''}${f.地点?`<p class="lt-meta">${e(f.地点)}</p>`:''}<p class="time-evidence-text">${e(body)}</p></div><div class="time-record-actions">${edit}</div></article>`;
}
function worldBody(s,book,currentDate){const version=s.domain?.current,selected=selectedWorldVersions(s.domain,s.config??s.draft),entries=selected.flatMap(v=>v.entries);return `<div class="time-stack"><p class="lt-meta">当前故事日期 · <time data-world-current-date>${currentDate?.day!=null?e(worldDateText(currentDate)):'尚未识别'}</time></p><div class="ui-action-grid time-entry-actions lt-work-actions">${button('预览请求','prepare',s.busy?'disabled':'','secondary')}${button(s.busy?'正在生成…':version?'更新世界':'生成初始世界','generate',s.busy?'disabled':'','primary')}</div>${!entries.length?'<p class="lt-meta">暂无世界动态</p>':Object.entries(WORLD_KINDS).map(([kind,label])=>{const list=entries.filter(row=>row.kind===kind);return list.length?(['weather','plot'].includes(kind)?list.map(entry=>entryCard(entry,book,currentDate,selected.find(v=>v.kind===kind).version)).join(''):`<section class="time-prompt-group time-world-group"><h2 class="time-group-heading">${label}</h2><div class="time-group-body">${list.map(entry=>entryCard(entry,book)).join('')}</div></section>`):'';}).join('')}${s.busy?'<p class="lt-status" role="status">世界动态正在后台生成</p>':''}</div>`;}
export function worldDynamicsMarkup(s,{theme,availability,currentDate=s.time?.currentDate}={}){const root=s.route==='world',book=['paper-letter','purple-glow'].includes(theme),title=s.route==='console'?'预设操作台':s.route==='books'?'选择世界书条目':s.route==='entry'?'编辑世界动态':'发送内容预览';let body='';
 const editorMain=s.route==='entry';
 if(s.status==='loading')body='<p class="lt-status">正在读取世界动态…</p>';else if(s.status==='failed')body=button('重新读取','reload');else if(s.route==='world')body=worldBody(s,book,currentDate);else if(s.route==='console')body=consoleBody(s);else if(s.route==='books')body=booksBody(s);else if(s.route==='entry')body=area('动态正文','entryText',s.entryText);else if(s.route==='preview')body=`<div class="time-stack">${(s.request?.messages??[]).map(m=>`<section><h2 class="time-group-heading">${e(m.role)}</h2><p class="time-evidence-text">${e(m.content)}</p></section>`).join('')}</div>`;

 const footer=root?`<footer class="lt-footer">${mainNavigation({policy:availability(),current:'time',attribute:'data-time-action',actions:{time:'nav'},attributes:{time:'data-route="home"'}})}</footer>`:`<footer class="lt-footer ui-action-footer"><div class="wk-editor-footer">${s.route==='entry'?button('删除','delete-entry','','danger'):button('取消','back')}${button(s.route==='preview'?(s.busy?'正在生成…':'生成'):s.route==='books'?'添加':'保存',s.route==='preview'?'generate':s.route==='console'?'save-config':s.route==='entry'?'save-entry':'accept-books',s.route==='preview'&&s.busy?'disabled':'','primary')}</div></footer>`;
 return `<section class="lantai lt-time ui-workspace ui-graphic-controls" data-ui-theme="${theme}" data-time-route="world" data-world-route="${e(s.route)}" aria-label="世界动态"><header class="lt-header ui-header ${root?'lt-header--root':'ui-header--centered'}">${root?`<div class="lt-root-top">${rootTitle('time')}<button type="button" class="ui-icon-button ui-button--tertiary" data-time-action="close" aria-label="关闭兰台"><img class="lt-icon" src="${new URL('./icons/close.svg',import.meta.url)}" alt=""></button></div><nav class="ui-tablist" aria-label="时间主导航">${[['home','日历'],['world','世界动态'],['manage','管理']].map(([route,label])=>`<button type="button" class="ui-button lt-type" data-time-action="nav" data-route="${route}" ${route==='world'?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`:`<button type="button" class="ui-icon-button ui-button--tertiary" data-world-action="back" aria-label="返回"><img class="lt-icon" src="${new URL('./icons/back.svg',import.meta.url)}" alt=""></button><h1 class="ui-page-title">${e(title)}</h1><button type="button" class="ui-icon-button ui-button--tertiary" data-time-action="close" aria-label="关闭兰台"><img class="lt-icon" src="${new URL('./icons/close.svg',import.meta.url)}" alt=""></button>`}</header><main class="lt-main ui-main${editorMain?" ui-main--editor":""}" tabindex="-1">${s.error?`<p class="lt-error" role="alert">${e(s.error)}</p>`:''}${s.status==='preparing'?'<p class="lt-status">正在准备请求…</p>':''}${body}</main>${footer}${s.waitVisible?`<div class="time-confirm" role="dialog" aria-modal="true" aria-label="世界动态正在生成"><p aria-hidden="true">😿</p><h2>世界还在努力生长……</h2><p>世界动态正在生成，请先等等，再开始下一轮故事。</p>${button('先关掉，我偏要继续','dismiss-wait')}</div>`:''}</section>`;
}
export function bindWorldDynamicsEvents(container,controller){
 let consoleScroll=0,consoleBookPurpose=null,composing=false;
 const leaveBooks=save=>{const books=controller.inspect().route==='books';controller.back(save);if(books){const main=container.querySelector('.lt-main');if(main)main.scrollTop=consoleScroll;container.querySelector(`[data-world-action="books"][data-purpose="${consoleBookPurpose}"]`)?.focus({preventScroll:true});}};
 const patchChoices=()=>{const draft=controller.inspect().draft;if(!draft)return;const story=container.querySelector('[data-world-story-controls]'),recent=container.querySelector('[data-world-recent-count]');if(story)story.hidden=!draft.readStory;if(recent)recent.hidden=draft.initialScope!=='recent';};
 const captureOpen=()=>{for(const n of container.querySelectorAll('details[data-world-open]'))controller.setOpen(n.dataset.worldOpen,n.open);};
 const focusIdea=(index,reveal=false)=>{const draft=controller.inspect().draft,next=draft?.ideas.length?container.querySelector(`[data-world-field="ideas.${Math.min(index,draft.ideas.length-1)}.name"]`):container.querySelector('[data-world-action="add-idea"]');next?.focus({preventScroll:true});if(reveal)next?.scrollIntoView?.({block:'nearest'});};
 const click=event=>{const node=event.target.closest('[data-world-action]');if(!node||node.disabled)return;captureOpen();const action=node.dataset.worldAction;if(action==='back')leaveBooks(false);else if(action==='accept-books')leaveBooks(true);else if(action==='save-config')void controller.saveConfig();else if(action==='books'){consoleScroll=container.querySelector('.lt-main')?.scrollTop??0;consoleBookPurpose=node.dataset.purpose;void controller.chooseBooks(node.dataset.purpose);}else if(action==='toggle'){event.preventDefault();event.stopPropagation();controller.toggle(node.dataset.path,true);node.setAttribute('aria-checked',String(node.getAttribute('aria-checked')!=='true'));patchChoices();}else if(action==='add-idea'){controller.addIdea();focusIdea(controller.inspect().draft.ideas.length-1,true);}else if(action==='remove-idea'){const index=+node.dataset.index;controller.removeIdea(index);focusIdea(index);}else if(action==='prepare')void controller.prepare();else if(action==='generate')void controller.generate();else if(action==='entry')controller.openEntry(node.dataset.id);else if(action==='save-entry')void controller.saveEntry();else if(action==='delete-entry')void controller.saveEntry(true);else if(action==='dismiss-wait')controller.dismissWait();else if(action==='reload')void controller.load();};
 const change=event=>{const n=event.target;if(n.matches('[data-world-ref]')){controller.toggleRef(n.dataset.book,n.dataset.uid,n.checked);return;}const path=n.dataset.worldField;if(!path)return;if(path==='entryText')controller.editEntry(n.value);else controller.edit(path,n.type==='number'?Number(n.value):n.value);if(n.type==='radio'&&n.checked)patchChoices();};
 const remember=event=>{const n=event.target;if(n.matches?.('details[data-world-open]')&&container.contains(n))controller.setOpen(n.dataset.worldOpen,n.open);};
 const keyboard=event=>{if(event.key!=='Escape'||event.isComposing||composing||event.keyCode===229||controller.inspect().route!=='books')return;event.preventDefault();event.stopPropagation();leaveBooks(false);};
 const startComposition=()=>{composing=true;},endComposition=()=>{composing=false;};
 container.addEventListener('click',click);container.addEventListener('input',change);container.addEventListener('change',change);container.addEventListener('toggle',remember,true);container.addEventListener('keydown',keyboard);container.addEventListener('compositionstart',startComposition);container.addEventListener('compositionend',endComposition);return()=>{container.removeEventListener('click',click);container.removeEventListener('input',change);container.removeEventListener('change',change);container.removeEventListener('toggle',remember,true);container.removeEventListener('keydown',keyboard);container.removeEventListener('compositionstart',startComposition);container.removeEventListener('compositionend',endComposition);};
}
